     1→module protocol::reserve;
     2→
     3→use sui::balance::{Self, Balance, Supply};
     4→use sui::coin::{Coin};
     5→use sui::dynamic_field;
     6→
     7→use protocol::ctoken::CToken;
     8→use protocol::error;
     9→use protocol::ctoken;
    10→use math::float::{Self, Decimal};
    11→use protocol::borrow_index::{Self, BorrowIndex};
    12→
    13→public struct Reserve<phantom MarketType> has key, store {
    14→    id: UID,
    15→
    16→    debt: Decimal,
    17→    cash_reserve: Decimal,
    18→
    19→    // cash equals to ReserveBalance.underlying_balance, it is required as util_rate requires query without generic type
    20→    cash: u64,
    21→    // total_suppy equals to ReserveBalance.ctoken_supply.supply_value, it is required as exchange_rate requires query without generic type
    22→    total_supply: u64,
    23→
    24→    borrow_index: BorrowIndex,
    25→}
    26→
    27→public struct ReserveBalanceKey has copy, drop, store {} 
    28→public struct ReserveBalance<phantom MarketType, phantom CoinType> has store {
    29→    underlying_balance: Balance<CoinType>,
    30→    ctoken_supply: Supply<CToken<MarketType, CoinType>>,
    31→}
    32→
    33→public struct ReserveFlashLoan<phantom MarketType, phantom CoinType> {
    34→    amount: u64,
    35→}
    36→
    37→// create a vault for storing underlying assets and market coin supplies
    38→public(package) fun new<MarketType, CoinType>(ctx: &mut TxContext, now: u64): Reserve<MarketType> {
    39→    let mut reserve = Reserve {
    40→        id: object::new(ctx),
    41→        cash: 0,
    42→        debt: float::zero(),
    43→        cash_reserve: float::zero(),
    44→        total_supply: 0,
    45→
    46→        borrow_index: borrow_index::new(now),
    47→    };
    48→
    49→    dynamic_field::add(
    50→        &mut reserve.id,
    51→        ReserveBalanceKey {},
    52→        ReserveBalance<MarketType, CoinType> {
    53→            underlying_balance: balance::zero<CoinType>(),
    54→            ctoken_supply: balance::create_supply(ctoken::new()),
    55→        }
    56→    );
    57→
    58→    reserve
    59→}
    60→
    61→public(package) fun debt<MarketType>(self: &Reserve<MarketType>): &Decimal { &self.debt }
    62→
    63→public(package) fun borrow_index<MarketType>(self: &Reserve<MarketType>): &BorrowIndex { &self.borrow_index }
    64→
    65→public(package) fun util_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    66→    if (self.debt.is_zero()) {
    67→        return float::from_quotient(0, 1)
    68→    };
    69→
    70→    let denominator = self.cash_plus_borrows_minus_reserves();
    71→    self.debt.div(denominator)
    72→}
    73→
    74→public(package) fun cash_plus_borrows_minus_reserves<MarketType,>(self: &Reserve<MarketType>): Decimal {
    75→    self.debt.add_u64(self.cash).sub(self.cash_reserve)
    76→}
    77→
    78→public(package) fun protocol_reserve<MarketType>(self: &Reserve<MarketType>): u64 {
    79→    self.cash_reserve.floor()
    80→}
    81→
    82→public(package) fun total_deposit_plus_interest<MarketType,>(self: &Reserve<MarketType>): Decimal {
    83→    self.exchange_rate().mul_u64(self.total_supply)
    84→}
    85→
    86→/// Caller should ensure this asset can be collateral
    87→public(package) fun deposit_limit_breached<MarketType>(self: &Reserve<MarketType>, increment: u64, limit: u64): bool {
    88→    let total_deposit_plus_interest = self.total_deposit_plus_interest();
    89→    total_deposit_plus_interest.ceil() + increment - self.cash_reserve.ceil() > limit
    90→}
    91→
    92→public(package) fun exchange_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    93→    if (self.total_supply == 0) {
    94→        return float::from_quotient(1, 1)
    95→    };
    96→
    97→    let numerator = self.cash_plus_borrows_minus_reserves();
    98→    let denominator = float::from(self.total_supply);
    99→
   100→    numerator.div(denominator)
   101→}
   102→
   103→// ===================== Update Functions ================
   104→
   105→public(package) fun calculate_borrow_index<MarketType>(
   106→    self: &Reserve<MarketType>,
   107→    interest_rate: Decimal,
   108→    now: u64,
   109→): Decimal {
   110→    let borrow_index_prior = self.borrow_index.value();
   111→
   112→    // if the interest has been accrued, skip
   113→    let last_updated = self.borrow_index.last_updated();
   114→    if (last_updated == now) {
   115→        return borrow_index_prior
   116→    };
   117→
   118→    let simple_interest_factor = interest_rate.mul_u64(now - last_updated);
   119→
   120→    // mul_ScalarTruncateAddUInt(simpleInterestFactor, borrowIndexPrior, borrowIndexPrior);
   121→    simple_interest_factor.mul(borrow_index_prior).add(borrow_index_prior)
   122→}
   123→
   124→/// Increase the interest owned
   125→public(package) fun accrue_interest<MarketType>(
   126→    self: &mut Reserve<MarketType>,
   127→    reserve_factor: Decimal,
   128→    interest_rate: Decimal,
   129→    now: u64,
   130→) {
   131→    // if the interest has been accrued, skip
   132→    let last_updated = self.borrow_index.last_updated();
   133→    if (last_updated == now) {
   134→        return
   135→    };
   136→
   137→    let borrow_index_prior = self.borrow_index.value();
   138→
   139→    let simple_interest_factor = interest_rate.mul_u64(now - last_updated);
   140→    let interest_accumulated = self.debt.mul(simple_interest_factor);
   141→
   142→    self.debt = self.debt.add(interest_accumulated);
   143→    self.cash_reserve = self.cash_reserve.add(reserve_factor.mul(interest_accumulated));
   144→
   145→    // mul_ScalarTruncateAddUInt(simpleInterestFactor, borrowIndexPrior, borrowIndexPrior);
   146→    let new_borrow_index_value = simple_interest_factor.mul(borrow_index_prior).add(borrow_index_prior);
   147→
   148→    self.borrow_index.set_value(new_borrow_index_value, now);
   149→}
   150→
   151→/// Calculate how much market coin should be minted
   152→public(package) fun mint_ctokens<MarketType, CoinType>(
   153→    self: &mut Reserve<MarketType>,
   154→    coin: Coin<CoinType>,
   155→): Balance<CToken<MarketType, CoinType>> {
   156→    let collateral_amount = coin.value();
   157→    assert!(collateral_amount > 0, error::reserve_zero_coin_not_allowed());
   158→
   159→    // TODO: ensure small truncated number will not impact accuracy
   160→    let mint_amount = float::int_div(collateral_amount, self.exchange_rate());
   161→
   162→    self.deposit_underlying(coin);
   163→    self.increase_ctoken_supply(mint_amount)
   164→}
   165→
   166→public(package) fun liquidate_ctokens<MarketType, CoinType>(
   167→    self: &mut Reserve<MarketType>,
   168→    ctokens: Coin<CToken<MarketType, CoinType>>,
   169→    liq_revenue_factor: Decimal,
   170→): Balance<CoinType> {
   171→    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());
   172→
   173→    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());
   174→
   175→    let protocol_seize_amount = liq_revenue_factor.int_mul(redeem_collateral_amount);
   176→    let liquidator_seize_amount = redeem_collateral_amount - protocol_seize_amount;
   177→
   178→    self.cash_reserve = self.cash_reserve.add(math::float::from(protocol_seize_amount));
   179→
   180→    self.decrease_ctoken_supply(ctokens.into_balance());
   181→    self.withdraw_underlying(liquidator_seize_amount)
   182→}
   183→
   184→public(package) fun burn_ctokens<MarketType, CoinType>(
   185→    self: &mut Reserve<MarketType>,
   186→    ctokens: Coin<CToken<MarketType, CoinType>>,
   187→): Balance<CoinType> {
   188→    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());
   189→
   190→    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());
   191→
   192→    self.decrease_ctoken_supply(ctokens.into_balance());
   193→    self.withdraw_underlying(redeem_collateral_amount)
   194→}
   195→
   196→public(package) fun borrow_amount<MarketType, CoinType>(self: &mut Reserve<MarketType>, amount: u64): Balance<CoinType> {
   197→    assert!(self.cash - self.cash_reserve.ceil() > amount, error::reserve_not_enough_error());
   198→
   199→    self.debt = self.debt.add_u64(amount);
   200→    self.withdraw_underlying(amount)
   201→}
   202→
   203→public(package) fun repay_amount<MarketType, CoinType>(self: &mut Reserve<MarketType>, coin: Coin<CoinType>) {
   204→    let repay_amount = float::from(coin.value());
   205→    
   206→    if (self.debt.lt(repay_amount)) {
   207→        let total_debt = self.debt.ceil();
   208→
   209→        // repay amount is more than debt, considered as donation to reserve
   210→        self.cash_reserve = self.cash_reserve.add_u64( coin.value() - total_debt);
   211→        self.debt = math::float::zero();
   212→    } else {
   213→        self.debt = self.debt.sub(repay_amount);
   214→    };
   215→
   216→    self.deposit_underlying(coin);
   217→}
   218→
   219→public(package) fun amount<MarketType, CoinType>(self: &ReserveFlashLoan<MarketType, CoinType>): u64 {
   220→    self.amount
   221→}
   222→
   223→/// Returns a hot potato ReserveFlashLoan along with the coin. Technically there is no need to but adding this extra
   224→/// type for reserve module to know all lend flash loans are properly paid. Fees are extra.
   225→public(package) fun borrow_flash_loan<MarketType, CoinType>(
   226→    self: &mut Reserve<MarketType>,
   227→    amount: u64,
   228→): (Balance<CoinType>, ReserveFlashLoan<MarketType, CoinType>) {
   229→    // allow flash loan to borrow reserves
   230→    assert!(amount < self.cash, error::reserve_flash_loan_more_than_cash());
   231→    (self.flash_loan_withdraw(amount), ReserveFlashLoan { amount })
   232→}
   233→
   234→public(package) fun repay_flash_loan<MarketType, CoinType>(
   235→    self: &mut Reserve<MarketType>,
   236→    
   237→    loan: ReserveFlashLoan<MarketType, CoinType>,
   238→    coin: Coin<CoinType>,
   239→
   240→    fee: Coin<CoinType>,
   241→) {
   242→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   243→
   244→    let ReserveFlashLoan { amount } = loan;
   245→    assert!(coin.value() == amount, error::reserve_flash_loan_not_paid_enough());
   246→    reserve_token_balance.underlying_balance.join(coin.into_balance());
   247→
   248→    // fee is extra cash for the cash reserve
   249→    if (fee.value() == 0) {
   250→        fee.destroy_zero();
   251→        return
   252→    };
   253→    self.increase_reserve_only<MarketType, CoinType>(fee);
   254→}
   255→
   256→/// Take cash_reserve of the protocol from the reserve
   257→public(package) fun take_revenue<MarketType, CoinType>(self: &mut Reserve<MarketType>, amount: u64): Balance<CoinType> {
   258→    let amount_decimal = float::from(amount);
   259→    assert!(self.cash_reserve.ge(amount_decimal), error::take_too_much_revenue());
   260→
   261→    self.cash_reserve = self.cash_reserve.sub(amount_decimal);
   262→    self.withdraw_underlying(amount)
   263→}
   264→
   265→fun increase_ctoken_supply<MarketType, CoinType>(
   266→    self: &mut Reserve<MarketType>,
   267→    amount: u64,
   268→): Balance<CToken<MarketType, CoinType>> {
   269→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   270→
   271→    self.total_supply = self.total_supply + amount;
   272→    reserve_token_balance.ctoken_supply.increase_supply(amount)
   273→}
   274→
   275→fun decrease_ctoken_supply<MarketType, CoinType>(
   276→    self: &mut Reserve<MarketType>,
   277→    balance: Balance<CToken<MarketType, CoinType>>,
   278→){
   279→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   280→
   281→    self.total_supply = self.total_supply - balance.value();
   282→    reserve_token_balance.ctoken_supply.decrease_supply(balance);
   283→}
   284→
   285→fun increase_reserve_only<MarketType, CoinType>(
   286→    self: &mut Reserve<MarketType>,
   287→    coin: Coin<CoinType>,
   288→) {
   289→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   290→
   291→    self.cash_reserve = self.cash_reserve.add(float::from(coin.value()));
   292→    self.cash = self.cash + coin.value();
   293→    reserve_token_balance.underlying_balance.join(coin.into_balance());
   294→}
   295→
   296→fun deposit_underlying<MarketType, CoinType>(
   297→    self: &mut Reserve<MarketType>,
   298→    coin: Coin<CoinType>,
   299→) {
   300→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   301→
   302→    self.cash = self.cash + coin.value();
   303→    reserve_token_balance.underlying_balance.join(coin.into_balance());
   304→}
   305→
   306→fun withdraw_underlying<MarketType, CoinType>(
   307→    self: &mut Reserve<MarketType>,
   308→    amount: u64,
   309→): Balance<CoinType> {
   310→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   311→
   312→    self.cash = self.cash - amount;
   313→    assert!(self.cash >= self.cash_reserve.ceil(), error::market_cash_reserve_not_enough());
   314→
   315→    reserve_token_balance.underlying_balance.split(amount)
   316→}
   317→
   318→fun flash_loan_withdraw<MarketType, CoinType>(
   319→    self: &mut Reserve<MarketType>,
   320→    amount: u64,
   321→): Balance<CoinType> {
   322→    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
   323→    reserve_token_balance.underlying_balance.split(amount)
   324→}
