module protocol::reserve;

use sui::balance::{Self, Balance, Supply};
use sui::coin::{Coin};
use sui::dynamic_field;

use protocol::ctoken::CToken;
use protocol::error;
use protocol::ctoken;
use math::float::{Self, Decimal};
use protocol::borrow_index::{Self, BorrowIndex};

public struct Reserve<phantom MarketType> has key, store {
    id: UID,

    debt: Decimal,
    cash_reserve: Decimal,

    // cash equals to ReserveBalance.underlying_balance, it is required as util_rate requires query without generic type
    cash: u64,
    // total_suppy equals to ReserveBalance.ctoken_supply.supply_value, it is required as exchange_rate requires query without generic type
    total_supply: u64,

    borrow_index: BorrowIndex,
}

public struct ReserveBalanceKey has copy, drop, store {} 
public struct ReserveBalance<phantom MarketType, phantom CoinType> has store {
    underlying_balance: Balance<CoinType>,
    ctoken_supply: Supply<CToken<MarketType, CoinType>>,
}

public struct ReserveFlashLoan<phantom MarketType, phantom CoinType> {
    amount: u64,
}

// create a vault for storing underlying assets and market coin supplies
public(package) fun new<MarketType, CoinType>(ctx: &mut TxContext, now: u64): Reserve<MarketType> {
    let mut reserve = Reserve {
        id: object::new(ctx),
        cash: 0,
        debt: float::zero(),
        cash_reserve: float::zero(),
        total_supply: 0,

        borrow_index: borrow_index::new(now),
    };

    dynamic_field::add(
        &mut reserve.id,
        ReserveBalanceKey {},
        ReserveBalance<MarketType, CoinType> {
            underlying_balance: balance::zero<CoinType>(),
            ctoken_supply: balance::create_supply(ctoken::new()),
        }
    );

    reserve
}

public(package) fun debt<MarketType>(self: &Reserve<MarketType>): &Decimal { &self.debt }

public(package) fun borrow_index<MarketType>(self: &Reserve<MarketType>): &BorrowIndex { &self.borrow_index }

public(package) fun util_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    if (self.debt.is_zero()) {
        return float::from_quotient(0, 1)
    };

    let denominator = self.cash_plus_borrows_minus_reserves();
    self.debt.div(denominator)
}

public(package) fun cash_plus_borrows_minus_reserves<MarketType,>(self: &Reserve<MarketType>): Decimal {
    self.debt.add_u64(self.cash).sub(self.cash_reserve)
}

public(package) fun protocol_reserve<MarketType>(self: &Reserve<MarketType>): u64 {
    self.cash_reserve.floor()
}

public(package) fun total_deposit_plus_interest<MarketType,>(self: &Reserve<MarketType>): Decimal {
    self.exchange_rate().mul_u64(self.total_supply)
}

/// Caller should ensure this asset can be collateral
public(package) fun deposit_limit_breached<MarketType>(self: &Reserve<MarketType>, increment: u64, limit: u64): bool {
    let total_deposit_plus_interest = self.total_deposit_plus_interest();
    total_deposit_plus_interest.ceil() + increment - self.cash_reserve.ceil() > limit
}

public(package) fun exchange_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    if (self.total_supply == 0) {
        return float::from_quotient(1, 1)
    };

    let numerator = self.cash_plus_borrows_minus_reserves();
    let denominator = float::from(self.total_supply);

    numerator.div(denominator)
}

// ===================== Update Functions ================

public(package) fun calculate_borrow_index<MarketType>(
    self: &Reserve<MarketType>,
    interest_rate: Decimal,
    now: u64,
): Decimal {
    let borrow_index_prior = self.borrow_index.value();

    // if the interest has been accrued, skip
    let last_updated = self.borrow_index.last_updated();
    if (last_updated == now) {
        return borrow_index_prior
    };

    let simple_interest_factor = interest_rate.mul_u64(now - last_updated);

    // mul_ScalarTruncateAddUInt(simpleInterestFactor, borrowIndexPrior, borrowIndexPrior);
    simple_interest_factor.mul(borrow_index_prior).add(borrow_index_prior)
}

/// Increase the interest owned
public(package) fun accrue_interest<MarketType>(
    self: &mut Reserve<MarketType>,
    reserve_factor: Decimal,
    interest_rate: Decimal,
    now: u64,
) {
    // if the interest has been accrued, skip
    let last_updated = self.borrow_index.last_updated();
    if (last_updated == now) {
        return
    };

    let borrow_index_prior = self.borrow_index.value();

    let simple_interest_factor = interest_rate.mul_u64(now - last_updated);
    let interest_accumulated = self.debt.mul(simple_interest_factor);

    self.debt = self.debt.add(interest_accumulated);
    self.cash_reserve = self.cash_reserve.add(reserve_factor.mul(interest_accumulated));

    // mul_ScalarTruncateAddUInt(simpleInterestFactor, borrowIndexPrior, borrowIndexPrior);
    let new_borrow_index_value = simple_interest_factor.mul(borrow_index_prior).add(borrow_index_prior);

    self.borrow_index.set_value(new_borrow_index_value, now);
}

/// Calculate how much market coin should be minted
public(package) fun mint_ctokens<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    coin: Coin<CoinType>,
): Balance<CToken<MarketType, CoinType>> {
    let collateral_amount = coin.value();
    assert!(collateral_amount > 0, error::reserve_zero_coin_not_allowed());

    // TODO: ensure small truncated number will not impact accuracy
    let mint_amount = float::int_div(collateral_amount, self.exchange_rate());

    self.deposit_underlying(coin);
    self.increase_ctoken_supply(mint_amount)
}

public(package) fun liquidate_ctokens<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    ctokens: Coin<CToken<MarketType, CoinType>>,
    liq_revenue_factor: Decimal,
): Balance<CoinType> {
    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());

    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());

    let protocol_seize_amount = liq_revenue_factor.int_mul(redeem_collateral_amount);
    let liquidator_seize_amount = redeem_collateral_amount - protocol_seize_amount;

    self.cash_reserve = self.cash_reserve.add(math::float::from(protocol_seize_amount));

    self.decrease_ctoken_supply(ctokens.into_balance());
    self.withdraw_underlying(liquidator_seize_amount)
}

public(package) fun burn_ctokens<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    ctokens: Coin<CToken<MarketType, CoinType>>,
): Balance<CoinType> {
    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());

    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());

    self.decrease_ctoken_supply(ctokens.into_balance());
    self.withdraw_underlying(redeem_collateral_amount)
}

public(package) fun borrow_amount<MarketType, CoinType>(self: &mut Reserve<MarketType>, amount: u64): Balance<CoinType> {
    assert!(self.cash - self.cash_reserve.ceil() > amount, error::reserve_not_enough_error());

    self.debt = self.debt.add_u64(amount);
    self.withdraw_underlying(amount)
}

public(package) fun repay_amount<MarketType, CoinType>(self: &mut Reserve<MarketType>, coin: Coin<CoinType>) {
    let repay_amount = float::from(coin.value());

    if (self.debt.lt(repay_amount)) {
        let total_debt = self.debt.ceil();

        // repay amount is more than debt, considered as donation to reserve
        self.cash_reserve = self.cash_reserve.add_u64( coin.value() - total_debt);
        self.debt = math::float::zero();
    } else {
        self.debt = self.debt.sub(repay_amount);
    };

    self.deposit_underlying(coin);
}

public(package) fun amount<MarketType, CoinType>(self: &ReserveFlashLoan<MarketType, CoinType>): u64 {
    self.amount
}

/// Returns a hot potato ReserveFlashLoan along with the coin. Technically there is no need to but adding this extra
/// type for reserve module to know all lend flash loans are properly paid. Fees are extra.
public(package) fun borrow_flash_loan<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    amount: u64,
): (Balance<CoinType>, ReserveFlashLoan<MarketType, CoinType>) {
    // allow flash loan to borrow reserves
    assert!(amount < self.cash, error::reserve_flash_loan_more_than_cash());
    (self.flash_loan_withdraw(amount), ReserveFlashLoan { amount })
}

public(package) fun repay_flash_loan<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,

    loan: ReserveFlashLoan<MarketType, CoinType>,
    coin: Coin<CoinType>,

    fee: Coin<CoinType>,
) {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    let ReserveFlashLoan { amount } = loan;
    assert!(coin.value() == amount, error::reserve_flash_loan_not_paid_enough());
    reserve_token_balance.underlying_balance.join(coin.into_balance());

    // fee is extra cash for the cash reserve
    if (fee.value() == 0) {
        fee.destroy_zero();
        return
    };
    self.increase_reserve_only<MarketType, CoinType>(fee);
}

/// Take cash_reserve of the protocol from the reserve
public(package) fun take_revenue<MarketType, CoinType>(self: &mut Reserve<MarketType>, amount: u64): Balance<CoinType> {
    let amount_decimal = float::from(amount);
    assert!(self.cash_reserve.ge(amount_decimal), error::take_too_much_revenue());

    self.cash_reserve = self.cash_reserve.sub(amount_decimal);
    self.withdraw_underlying(amount)
}

fun increase_ctoken_supply<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    amount: u64,
): Balance<CToken<MarketType, CoinType>> {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.total_supply = self.total_supply + amount;
    reserve_token_balance.ctoken_supply.increase_supply(amount)
}

fun decrease_ctoken_supply<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    balance: Balance<CToken<MarketType, CoinType>>,
){
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.total_supply = self.total_supply - balance.value();
    reserve_token_balance.ctoken_supply.decrease_supply(balance);
}

fun increase_reserve_only<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    coin: Coin<CoinType>,
) {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.cash_reserve = self.cash_reserve.add(float::from(coin.value()));
    self.cash = self.cash + coin.value();
    reserve_token_balance.underlying_balance.join(coin.into_balance());
}

fun deposit_underlying<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    coin: Coin<CoinType>,
) {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.cash = self.cash + coin.value();
    reserve_token_balance.underlying_balance.join(coin.into_balance());
}

fun withdraw_underlying<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    amount: u64,
): Balance<CoinType> {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.cash = self.cash - amount;
    assert!(self.cash >= self.cash_reserve.ceil(), error::market_cash_reserve_not_enough());

    reserve_token_balance.underlying_balance.split(amount)
}

fun flash_loan_withdraw<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    amount: u64,
): Balance<CoinType> {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});
    reserve_token_balance.underlying_balance.split(amount)
}

